package com.buildertoolbox.client.settings;
import java.util.function.*; public class Setting<T> {public double min=-Double.MAX_VALUE,max=Double.MAX_VALUE,sliderMin,sliderMax;public boolean slider; public final String name,description; public String title; public final T defaultValue; public final BooleanSupplier visible; protected T value; private final Consumer<T> changed; public Setting(String n,String d,T value,BooleanSupplier v,Consumer<T> c){name=n;title=n;description=d;defaultValue=value;this.value=value;visible=v;changed=c;} public T get(){return value;} public boolean set(T v){if(v instanceof Number n && (!Double.isFinite(n.doubleValue())||n.doubleValue()<min||n.doubleValue()>max))return false;if(java.util.Objects.equals(value,v))return true;value=v;if(changed!=null)changed.accept(v);return true;} public void reset(){set(defaultValue);} public boolean isVisible(){return visible.getAsBoolean();} }